            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"150\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"215\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">WHY A TRAGEDY?</text><text x=\"550\" y=\"270\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Later Rand heroes win.</text><text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">What is different here?</text><rect x=\"150\" y=\"430\" width=\"370\" height=\"140\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"335\" y=\"510\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">LATER NOVELS</text><rect x=\"580\" y=\"430\" width=\"370\" height=\"140\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"765\" y=\"510\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">WE THE LIVING</text></svg>",
