            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"160\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"550\" y=\"230\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">THE TURNING POINT</text><text x=\"550\" y=\"280\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Illness plus a closed system</text><rect x=\"150\" y=\"440\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"510\" text-anchor=\"middle\" fill=\"#f59e0b\" font-size=\"22\">Money is not enough -- permission is needed</text><rect x=\"150\" y=\"620\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"690\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-size=\"22\">Next: the choice Kira makes</text></svg>",
