            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"160\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"230\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">THE 1986 RELEASE</text><text x=\"550\" y=\"285\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Remake, original, or restoration?</text><text x=\"550\" y=\"325\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Think about who worked on it and when</text><rect x=\"150\" y=\"450\" width=\"370\" height=\"120\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"335\" y=\"520\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">1942: two parts</text><rect x=\"580\" y=\"450\" width=\"370\" height=\"120\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"765\" y=\"520\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">1986: one feature</text></svg>",
